class ModuleInfo:
    def __init__(self, name, paths):
        self.py_src = False
        self.pkg_dir = False
        path = None

        if imp is None:
            # don't pretend this is a top-level module, prefix the rest of the namespace
            self._info = info = importlib.machinery.PathFinder.find_spec('ansible.module_utils.' + name, paths)
            if info is not None:
                self.py_src = os.path.splitext(info.origin)[1] in importlib.machinery.SOURCE_SUFFIXES
                self.pkg_dir = info.origin.endswith('/__init__.py')
                path = info.origin
            else:
                raise ImportError("No module named '%s'" % name)
        else:
            self._info = info = imp.find_module(name, paths)
            self.py_src = info[2][2] == imp.PY_SOURCE
            self.pkg_dir = info[2][2] == imp.PKG_DIRECTORY
            if self.pkg_dir:
                path = os.path.join(info[1], '__init__.py')
            else:
                path = info[1]

        self.path = path

    def get_source(self):
        if imp and self.py_src:
            try:
                return self._info[0].read()
            finally:
                self._info[0].close()
        return _slurp(self.path)

    def __repr__(self):
        return 'ModuleInfo: py_src=%s, pkg_dir=%s, path=%s' % (self.py_src, self.pkg_dir, self.path)


class ModuleUtilLocatorBase:
    """Find a module, package, or routed name without executing module source."""

    prefix_length = 0
    redirect_first = False

    def __init__(self, fq_name_parts, is_ambiguous=False, child_is_redirected=False):
        self.fq_name_parts = tuple(fq_name_parts)
        self.is_ambiguous = is_ambiguous and len(self.fq_name_parts) > self.prefix_length + 1
        self.child_is_redirected = child_is_redirected
        self.found = self.redirected = self.is_package = False
        self.name_parts = self.fq_name_parts
        self.source_code = self.output_path = self.source_path = self.redirect_target = None
        for candidate in self.candidate_names:
            methods = (self._try_redirect, self._try_local) if self.redirect_first else (self._try_local, self._try_redirect)
            if any(method(candidate) for method in methods):
                break

    @property
    def candidate_names(self):
        result = [self.fq_name_parts]
        if self.is_ambiguous:
            result.append(self.fq_name_parts[:-1])
        return result

    def candidate_names_joined(self):
        return ['.'.join(p) for p in self.candidate_names]

    def _set_source(self, parts, source, path, package=False):
        self.found, self.is_package = True, package
        self.name_parts, self.source_code, self.source_path = parts, source, path
        self.output_path = '/'.join(parts) + ('/__init__.py' if package else '.py')
        return True

    def _set_route(self, parts, entry, collection):
        tombstone = entry.get('tombstone') or {}
        if tombstone:
            raise AnsibleError('%s in collection %s: %s (removal version: %s, removal date: %s)' %
                               ('.'.join(parts), collection, tombstone.get('warning_text') or 'removed',
                                tombstone.get('removal_version'), tombstone.get('removal_date')))
        deprecation = entry.get('deprecation') or {}
        if deprecation and not self.child_is_redirected:
            display.deprecated(deprecation.get('warning_text') or '%s has been deprecated' % '.'.join(parts),
                               version=deprecation.get('removal_version'), date=deprecation.get('removal_date'),
                               collection_name=collection)
        target = entry.get('redirect')
        if not target:
            return False
        target_parts = tuple(target.split('.'))
        if target_parts[0] != 'ansible_collections':
            target_parts = ('ansible_collections',) + target_parts[:2] + ('plugins', 'module_utils') + target_parts[2:]
        self.redirected, self.redirect_target = True, target_parts
        package = False
        if target_parts[:1] == ('ansible_collections',):
            resource = '/'.join(target_parts[3:]) + '/__init__.py'
            package = CollectionModuleUtilLocator._get_data('.'.join(target_parts[1:3]), resource) is not None
        return self._set_source(parts, "import sys\nimport %s as mod\nsys.modules[%r] = mod\n" %
                                ('.'.join(target_parts), '.'.join(parts)), '<redirect>', package)


class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 2

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None, child_is_redirected=False):
        self.mu_paths = mu_paths if mu_paths is not None else [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)] + [_MODULE_UTILS_PATH]
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)

    def _try_local(self, parts):
        relative = parts[2:]
        if not relative:
            return False
        try:
            info = ModuleInfo(relative[-1], [os.path.join(p, *relative[:-1]) for p in self.mu_paths])
        except ImportError:
            return False
        if not info.pkg_dir and not info.py_src:
            raise AnsibleError('Could not find python source for imported module support code for %s' % '.'.join(parts))
        return self._set_source(parts, info.get_source(), info.path, info.pkg_dir)

    def _try_redirect(self, parts):
        if len(parts) != 3:
            return False
        entry = _get_collection_metadata('ansible.builtin').get('plugin_routing', {}).get('module_utils', {}).get(parts[-1], {})
        return self._set_route(parts, entry, 'ansible.builtin') if entry else False


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 5
    redirect_first = True

    @staticmethod
    def _get_data(collection, resource):
        try:
            return pkgutil.get_data('ansible_collections.' + collection, resource)
        except (IOError, OSError):
            return None

    def _metadata(self, parts):
        collection = '.'.join(parts[1:3])
        try:
            return collection, _get_collection_metadata(collection)
        except ValueError as e:
            raise AnsibleError(to_native(e))

    def _try_redirect(self, parts):
        if len(parts) <= 5:
            return False
        collection, metadata = self._metadata(parts)
        routes = metadata.get('plugin_routing', {}).get('module_utils', {})
        for end in range(len(parts), 5, -1):
            entry = routes.get('.'.join(parts[5:end]), {})
            if not entry:
                continue
            if end == len(parts):
                return self._set_route(parts, entry, collection)
            if entry.get('tombstone'):
                return self._set_route(parts[:end], entry, collection)
            if entry.get('redirect'):
                routed = dict(entry)
                routed['redirect'] = entry['redirect'] + '.' + '.'.join(parts[end:])
                if self.is_ambiguous:
                    target = routed['redirect'].split('.')
                    if target[0] != 'ansible_collections':
                        target = ['ansible_collections'] + target[:2] + ['plugins', 'module_utils'] + target[2:]
                    resource = '/'.join(target[3:])
                    target_collection = '.'.join(target[1:3])
                    if (self._get_data(target_collection, resource + '.py') is None and
                            self._get_data(target_collection, resource + '/__init__.py') is None):
                        continue
                return self._set_route(parts, routed, collection)
        return False

    def _try_local(self, parts):
        if len(parts) <= 5:
            return False
        collection, unused = self._metadata(parts)
        resource = '/'.join(parts[3:])
        source = self._get_data(collection, resource + '/__init__.py')
        if source is not None:
            return self._set_source(parts, source, resource + '/__init__.py', True)
        source = self._get_data(collection, resource + '.py')
        if source is not None:
            return self._set_source(parts, source, resource + '.py')
        return False



